Given an array arr[] where each element shows the amount of money in a row of houses built in a line. A robber wants to steal money, but cannot rob two houses adjacent to each other because it will set off an alarm.Find the maximum money the robber can steal without robbing two adjacent houses.Examples: Input: arr[] = [6, 7, 1, 3, 8, 2, 4]Output: 19Explanation: The thief will steal from house 1, 3, 5 and 7, total money = 6 + 1 + 8 + 4 = 19.Input: arr[] = [5, 3, 4, 11, 2]Output: 16Explanation: Thief will steal from house 1 and 4, total money = 5 + 11 = 16.Try It YourselfTable of Content[Naive Approach] Using Recursion- O(2^n) Time and O(n) Space[Better Approach] Using Memoization - O(n) Time and O(n) Space [Expected Approach 1] Using Tabulation - O(n) Time and O(n) Space[Expected Approach 2] Space-Optimized DP - O(n) Time and O(1) Space[Naive Approach] Using Recursion- O(2^n) Time and O(n) SpaceThe idea is to explore all the possibilities for each house using Recursion. We can start from the last house and for each house, we have two choices:Rob the current house and skip the house just before it.Skip the current house and move to the next house.
            C++

    //Driver Code Starts
#include <iostream>
#include <vector>
using namespace std;
//Driver Code Ends


// Calculate the maximum stolen value recursively
int findMaxSumRec(vector<int> &arr, int n) {

    // If no houses are left, return 0.
    if (n <= 0)  return 0;

  	// If only 1 house is left, rob it. 
    if (n == 1)  return arr[0];

    // Two Choices: Rob the nth house and do not rob the nth house 
    int pick = arr[n - 1] + findMaxSumRec(arr, n - 2);
    int notPick = findMaxSumRec(arr, n - 1);

    // Return the max of two choices
    return max(pick, notPick);
}

// Function to calculate the maximum stolen value
int findMaxSum(vector<int>&arr) {
    int n = arr.size();

    // Call the recursive function for n houses
  	return findMaxSumRec(arr, n);
}


//Driver Code Starts
int main() {
    vector<int> arr = {6, 7, 1, 3, 8, 2, 4};
    cout << findMaxSum(arr);
    return 0;
}

